  std::string ERROR_CODE{};
  std::string ERROR_MESSAGE{};
  std::vector<ppsProduct> PRODUCTS{};
  std::vector<std::string> ASSUMPTIONS{};
  std::unique_ptr<ppsTelemetryT> TELEMETRY{};
  PPST() = default;
